    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.hasseDeriv_apply",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R),\n  (Polynomial.hasseDeriv k) f = f.sum fun i r => (Polynomial.monomial (i - k)) (↑(i.choose k) * r)"
    },
    {
      "name": "Polynomial.hasseDeriv_one",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R], Polynomial.hasseDeriv 1 = Polynomial.derivative"
    },
    {
      "name": "MvPolynomial.finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) →\n  [inst : CommSemiring R] → (n : ℕ) → MvPolynomial (Fin (n + 1)) R ≃ₐ[R] Polynomial (MvPolynomial (Fin n) R)"
    },
    {
      "name": "Polynomial.Bivariate.Polynomial.Bivariate.pderiv_zero_equivMvPolynomial",
      "module_name": "Mathlib.Algebra.Polynomial.Bivariate",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] (p : Polynomial (Polynomial R)),\n  (MvPolynomial.pderiv 0) ((Polynomial.Bivariate.equivMvPolynomial R) p) =\n    (Polynomial.Bivariate.equivMvPolynomial R)\n      (PolynomialModule.equivPolynomialSelf (Polynomial.derivative'.mapCoeffs p))"
    }
  ]
}

